<?php
declare(strict_types=1);
namespace AM2050\Controllers;
use AM2050\Core\Request; use AM2050\Core\Response; use AM2050\Middleware\AuthMiddleware; use AM2050\Middleware\RoleMiddleware; use AM2050\Services\HouseholdService;
final class HouseholdController { public function __construct(private readonly AuthMiddleware $auth,private readonly HouseholdService $service){} private function actor(Request $request):array{$actor=$this->auth->require($request);RoleMiddleware::require($actor,'mobilizer',['headmaster','teacher','guardian']);return $actor;} public function list(Request $request):never{$actor=$this->actor($request);$result=$this->service->list($actor,$request->query);Response::paginate($result['data'],$result['page'],$result['limit'],$result['total']);} public function get(Request $request,array $params):never{Response::success($this->service->get($this->actor($request),$params['id']));} public function create(Request $request):never{Response::success($this->service->create($this->actor($request),$request->body()),201);} public function update(Request $request,array $params):never{Response::success($this->service->update($this->actor($request),$params['id'],$request->body()));} }
